基础工具安装 基础工具是Linux系统运行的核心组件，包括文件操作、文本处理、系统管理等基本功能。本章将详细介绍如何编译和安装这些基础工具。
🎯 核心工具概述 工具分类 LFS基础工具主要包括：
文件工具：cp, mv, rm, ls, cat, mkdir等 文本处理：grep, sed, awk, sort, uniq等 系统工具：ps, top, kill, mount, umount等 压缩工具：gzip, bzip2, xz等 网络工具：wget, curl等 🛠️ Gettext工具 编译Gettext # 切换到lfs用户 su - lfs # 创建构建目录 mkdir -pv $LFS/sources/basic_system cd $LFS/sources/basic_system # 解压Gettext源码 tar -xf $LFS/sources/gettext-0.21.tar.xz cd gettext-0.21 # 配置Gettext ./configure --disable-shared # 编译 make $LFS_MAKEFLAGS # 安装到临时位置 cp -v gettext-tools/src/{msgfmt,msgmerge,xgettext} /usr/bin 📦 Bison工具 编译Bison # 返回源码目录 cd $LFS/sources/basic_system # 解压Bison源码 tar -xf $LFS/sources/bison-3.8.2.tar.xz cd bison-3.8.2 # 配置Bison ./configure --prefix=/usr \ --docdir=/usr/share/doc/bison-3.8.2 # 编译 make $LFS_MAKEFLAGS # 安装 make install 🔧 Perl工具 编译Perl # 返回源码目录 cd $LFS/sources/basic_system # 解压Perl源码 tar -xf $LFS/sources/perl-5.36.0.tar.xz cd perl-5.36.0 # 配置Perl sh Configure -des \ -Dprefix=/usr \ -Dvendorprefix=/usr \ -Dprivlib=/usr/lib/perl5/5.36/core_perl \ -Darchlib=/usr/lib/perl5/5.36/core_perl \ -Dsitelib=/usr/lib/perl5/5.36/site_perl \ -Dvendorlib=/usr/lib/perl5/5.36/vendor_perl \ -Dvendorarch=/usr/lib/perl5/5.36/vendor_perl \ -Dman1dir=/usr/share/man/man1 \ -Dman3dir=/usr/share/man/man3 \ -Dpager=&#34;/usr/bin/less -isR&#34; \ -Duseshrplib \ -Dusethreads # 编译 make $LFS_MAKEFLAGS # 安装 make install # 清理不必要的文件 rm -rf /usr/lib/perl5/5.36/core_perl/{pod,man} 📚 Python工具 编译Python # 返回源码目录 cd $LFS/sources/basic_system # 解压Python源码 tar -xf $LFS/sources/Python-3.11.2.tar.xz cd Python-3.11.2 # 配置Python ./configure --prefix=/usr \ --enable-shared \ --without-ensurepip # 编译 make $LFS_MAKEFLAGS # 安装 make install # 创建符号链接 ln -sv /usr/bin/python3 /usr/bin/python 🗜️ Texinfo工具 编译Texinfo # 返回源码目录 cd $LFS/sources/basic_system # 解压Texinfo源码 tar -xf $LFS/sources/texinfo-7.0.2.tar.xz cd texinfo-7.0.2 # 配置Texinfo ./configure --prefix=/usr # 编译 make $LFS_MAKEFLAGS # 安装 make install 🔍 Util-linux工具 编译Util-linux # 返回源码目录 cd $LFS/sources/basic_system # 解压Util-linux源码 tar -xf $LFS/sources/util-linux-2.38.1.tar.xz cd util-linux-2.38.1 # 配置Util-linux ./configure --prefix=/usr \ --bindir=/usr/bin \ --libdir=/usr/lib \ --sbindir=/usr/sbin \ --disable-chfn-chsh \ --disable-login \ --disable-nologin \ --disable-su \ --disable-setpriv \ --disable-runuser \ --disable-pylibmount \ --disable-static \ --without-python \ runstatedir=/run # 编译 make $LFS_MAKEFLAGS # 安装 make install 📊 进度跟踪 构建状态监控 # 创建基础工具构建脚本 cat &gt; $LFS/build_base_tools.sh &lt;&lt; &#39;EOF&#39; #!/bin/bash # LFS基础工具构建脚本 set -e # 工具列表 tools=( &#34;gettext-0.21:gettext&#34; &#34;bison-3.8.2:bison&#34; &#34;perl-5.36.0:perl&#34; &#34;Python-3.11.2:python&#34; &#34;texinfo-7.0.2:texinfo&#34; &#34;util-linux-2.38.1:util-linux&#34; ) total_tools=${#tools[@]} completed=0 for tool_info in &#34;${tools[@]}&#34;; do IFS=&#39;:&#39; read -r package_name tool_name &lt;&lt;&lt; &#34;$tool_info&#34; echo &#34;=== 构建 $tool_name ($((completed + 1))/$total_tools) ===&#34; # 检查源码是否存在 if [ ! -f &#34;$LFS/sources/$package_name.tar.xz&#34; ]; then echo &#34;错误: $package_name 源码不存在&#34; exit 1 fi # 构建逻辑（根据工具不同而不同） case $tool_name in gettext) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name ./configure --disable-shared make $LFS_MAKEFLAGS cp -v gettext-tools/src/{msgfmt,msgmerge,xgettext} /usr/bin ;; bison) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name ./configure --prefix=/usr --docdir=/usr/share/doc/$package_name make $LFS_MAKEFLAGS make install ;; perl) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name sh Configure -des \ -Dprefix=/usr \ -Dvendorprefix=/usr \ -Dprivlib=/usr/lib/perl5/5.36/core_perl \ -Darchlib=/usr/lib/perl5/5.36/core_perl \ -Dsitelib=/usr/lib/perl5/5.36/site_perl \ -Dvendorlib=/usr/lib/perl5/5.36/vendor_perl \ -Dvendorarch=/usr/lib/perl5/5.36/vendor_perl \ -Dman1dir=/usr/share/man/man1 \ -Dman3dir=/usr/share/man/man3 \ -Dpager=&#34;/usr/bin/less -isR&#34; \ -Duseshrplib \ -Dusethreads make $LFS_MAKEFLAGS make install rm -rf /usr/lib/perl5/5.36/core_perl/{pod,man} ;; python) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name ./configure --prefix=/usr --enable-shared --without-ensurepip make $LFS_MAKEFLAGS make install ln -sv /usr/bin/python3 /usr/bin/python ;; texinfo) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name ./configure --prefix=/usr make $LFS_MAKEFLAGS make install ;; util-linux) cd $LFS/sources/basic_system tar -xf $LFS/sources/$package_name.tar.xz cd $package_name ./configure --prefix=/usr \ --bindir=/usr/bin \ --libdir=/usr/lib \ --sbindir=/usr/sbin \ --disable-chfn-chsh \ --disable-login \ --disable-nologin \ --disable-su \ --disable-setpriv \ --disable-runuser \ --disable-pylibmount \ --disable-static \ --without-python \ runstatedir=/run make $LFS_MAKEFLAGS make install ;; esac # 验证安装 echo &#34;验证 $tool_name 安装...&#34; case $tool_name in gettext) [ -x /usr/bin/msgfmt ] &amp;&amp; echo &#34;✓ gettext 安装成功&#34; || echo &#34;✗ gettext 安装失败&#34; ;; bison) [ -x /usr/bin/bison ] &amp;&amp; echo &#34;✓ bison 安装成功&#34; || echo &#34;✗ bison 安装失败&#34; ;; perl) [ -x /usr/bin/perl ] &amp;&amp; echo &#34;✓ perl 安装成功&#34; || echo &#34;✗ perl 安装失败&#34; ;; python) [ -x /usr/bin/python3 ] &amp;&amp; echo &#34;✓ python 安装成功&#34; || echo &#34;✗ python 安装失败&#34; ;; texinfo) [ -x /usr/bin/makeinfo ] &amp;&amp; echo &#34;✓ texinfo 安装成功&#34; || echo &#34;✗ texinfo 安装失败&#34; ;; util-linux) [ -x /usr/bin/mount ] &amp;&amp; echo &#34;✓ util-linux 安装成功&#34; || echo &#34;✗ util-linux 安装失败&#34; ;; esac completed=$((completed + 1)) echo &#34;进度: $completed/$total_tools 完成&#34; echo &#34;&#34; # 清理构建目录 cd $LFS/sources/basic_system rm -rf $package_name done echo &#34;=== 所有基础工具构建完成 ===&#34; EOF chmod +x $LFS/build_base_tools.sh 🧪 功能验证 工具可用性测试 # 创建验证脚本 cat &gt; $LFS/verify_base_tools.sh &lt;&lt; &#39;EOF&#39; #!/bin/bash # 基础工具验证脚本 echo &#34;=== LFS基础工具验证 ===&#34; # 定义要验证的工具 tools=( &#34;msgfmt:gettext&#34; &#34;bison:bison&#34; &#34;perl:perl&#34; &#34;python3:python&#34; &#34;makeinfo:texinfo&#34; &#34;mount:util-linux&#34; ) passed=0 total=${#tools[@]} for tool_info in &#34;${tools[@]}&#34;; do IFS=&#39;:&#39; read -r command tool_name &lt;&lt;&lt; &#34;$tool_info&#34; echo -n &#34;检查 $tool_name ($command)... &#34; if command -v &#34;$command&#34; &gt;/dev/null 2&gt;&amp;1; then echo &#34;✓ 可用&#34; # 基本功能测试 case $tool_name in gettext) $command --version &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 版本检查: ✓&#34; || echo &#34; 版本检查: ✗&#34; ;; bison) $command --version &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 版本检查: ✓&#34; || echo &#34; 版本检查: ✗&#34; ;; perl) $command -e &#39;print &#34;Hello from Perl\n&#34;&#39; &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 基本功能: ✓&#34; || echo &#34; 基本功能: ✗&#34; ;; python) $command -c &#39;print(&#34;Hello from Python&#34;)&#39; &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 基本功能: ✓&#34; || echo &#34; 基本功能: ✗&#34; ;; texinfo) $command --version &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 版本检查: ✓&#34; || echo &#34; 版本检查: ✗&#34; ;; util-linux) $command --version &gt;/dev/null 2&gt;&amp;1 &amp;&amp; echo &#34; 版本检查: ✓&#34; || echo &#34; 版本检查: ✗&#34; ;; esac passed=$((passed + 1)) else echo &#34;✗ 未找到&#34; fi done echo &#34;&#34; echo &#34;=== 验证结果 ===&#34; echo &#34;通过: $passed/$total&#34; if [ $passed -eq $total ]; then echo &#34;✓ 所有基础工具都已正确安装&#34; exit 0 else echo &#34;✗ 部分工具安装失败&#34; exit 1 fi EOF chmod +x $LFS/verify_base_tools.sh 🚨 常见问题 编译失败处理 # 如果某个工具编译失败： # 1. 检查依赖 echo &#34;检查依赖...&#34; # 2. 查看错误日志 echo &#34;查看构建日志...&#34; tail -50 $LFS/logs/build.log # 3. 重新配置 echo &#34;尝试重新配置...&#34; make clean ./configure [选项] # 4. 检查磁盘空间 df -h $LFS 依赖问题 # 检查工具依赖关系 echo &#34;检查gettext依赖...&#34; ldd /usr/bin/msgfmt echo &#34;检查perl依赖...&#34; ldd /usr/bin/perl echo &#34;检查python依赖...&#34; ldd /usr/bin/python3 版本兼容性 # 检查版本信息 echo &#34;工具版本信息:&#34; msgfmt --version | head -1 bison --version | head -1 perl --version | head -2 python3 --version makeinfo --version | head -1 mount --version 📊 构建统计 构建时间统计 # 记录构建时间 cat &gt; $LFS/log_build_times.sh &lt;&lt; &#39;EOF&#39; #!/bin/bash # 构建时间记录脚本 LOG_FILE=&#34;$LFS/logs/build_times.log&#34; log_time() { local tool_name=$1 local start_time=$2 local end_time=$3 local duration=$((end_time - start_time)) local minutes=$((duration / 60)) local seconds=$((duration % 60)) echo &#34;$(date &#39;+%Y-%m-%d %H:%M:%S&#39;) - $tool_name: ${minutes}分${seconds}秒&#34; &gt;&gt; &#34;$LOG_FILE&#34; echo &#34;$tool_name 构建时间: ${minutes}分${seconds}秒&#34; } # 在构建脚本中使用 # start_time=$(date +%s) # [构建命令] # end_time=$(date +%s) # log_time &#34;tool_name&#34; $start_time $end_time EOF chmod +x $LFS/log_build_times.sh 📚 相关资源 LFS官方文档 - 基础工具 GNU工具文档 Python官方文档 最近更新: {{ .Lastmod.Format &ldquo;2006-01-02&rdquo; }}

宿主系统配置 在开始LFS构建之前，需要确保宿主系统具有必要的工具和环境。本章将详细介绍如何配置宿主系统以支持LFS构建过程。
🖥️ 系统要求 硬件要求 CPU：x86_64架构，支持64位操作 内存：至少2GB，推荐4GB以上 磁盘空间：至少10GB可用空间用于LFS构建 网络：稳定的互联网连接用于下载源码 软件要求 宿主系统：现代Linux发行版（推荐Arch Linux、Ubuntu 18.04+、Fedora 30+） 内核版本：3.2或更高版本 编译器：GCC 5.2或更高版本 核心工具：bash、binutils、bison、bzip2、coreutils、diffutils、findutils、gawk、gcc、glibc、grep、gzip、m4、make、patch、perl、python3、sed、tar、texinfo、xz 🔧 环境检查 检查系统信息 # 检查Linux发行版 cat /etc/os-release # 检查内核版本 uname -a # 检查CPU架构 uname -m # 检查可用内存 free -h # 检查磁盘空间 df -h # 检查网络连接 ping -c 3 google.com 检查必要工具 # 检查编译器版本 gcc --version g++ --version # 检查核心工具 which bash binutils bison bzip2 coreutils diffutils findutils gawk glibc grep gzip m4 make patch perl python3 sed tar texinfo xz # 检查库依赖 ldd --version 📦 安装必要软件包 Arch Linux # 更新系统 sudo pacman -Syu # 安装基础开发工具 sudo pacman -S base-devel # 安装LFS特定工具 sudo pacman -S wget texinfo python # 可选：安装文档工具 sudo pacman -S man-db man-pages Ubuntu/Debian # 更新系统 sudo apt update &amp;&amp; sudo apt upgrade # 安装基础编译工具 sudo apt install build-essential # 安装LFS所需工具 sudo apt install wget texinfo python3 bison gawk # 安装文档工具 sudo apt install man-db manpages-dev Fedora/CentOS # 更新系统 sudo dnf update # 安装开发工具组 sudo dnf groupinstall &#34;Development Tools&#34; # 安装LFS特定工具 sudo dnf install wget texinfo python3 bison gawk # 安装文档 sudo dnf install man-db man-pages 检查安装结果 # 验证所有工具都已安装 echo &#34;Checking required tools...&#34; tools=&#34;bash binutils bison bzip2 coreutils diffutils findutils gawk gcc glibc grep gzip m4 make patch perl python3 sed tar texinfo xz&#34; for tool in $tools; do if ! command -v $tool &amp;&gt; /dev/null; then echo &#34;ERROR: $tool is not installed&#34; else echo &#34;OK: $tool found&#34; fi done 👤 用户和权限设置 创建LFS用户 # 创建lfs用户组 sudo groupadd lfs # 创建lfs用户 sudo useradd -s /bin/bash -g lfs -m -k /dev/null lfs # 设置密码 sudo passwd lfs # 授予lfs用户sudo权限（可选，用于安装软件包） echo &#39;lfs ALL=(ALL) NOPASSWD: ALL&#39; | sudo tee /etc/sudoers.d/lfs 切换到LFS用户 # 切换到lfs用户 su - lfs # 验证用户环境 whoami pwd echo $HOME 📁 目录结构设置 创建LFS目录 # 创建主LFS目录 sudo mkdir -pv $LFS # 设置正确的权限 sudo chown -v lfs:lfs $LFS # 验证目录权限 ls -ld $LFS 创建子目录结构 # 创建LFS子目录 mkdir -pv $LFS/{etc,var} $LFS/usr/{bin,lib,sbin} for i in bin lib sbin; do ln -sv usr/$i $LFS/$i done case $(uname -m) in x86_64) mkdir -pv $LFS/lib64 ;; esac # 创建工具目录 mkdir -pv $LFS/tools # 创建源码目录 mkdir -pv $LFS/sources # 设置目录权限 chown -v lfs:lfs $LFS/{usr{,/*},lib,var,etc,bin,sbin,tools} case $(uname -m) in x86_64) chown -v lfs:lfs $LFS/lib64 ;; esac 🔗 环境变量配置 设置LFS环境变量 # 在~/.bashrc中添加LFS环境变量 cat &gt;&gt; ~/.bashrc &lt;&lt; &#34;EOF&#34; # LFS环境变量 export LFS=/mnt/lfs export LFS_TGT=$(uname -m)-lfs-linux-gnu export PATH=$LFS/tools/bin:$PATH export CONFIG_SITE=$LFS/usr/share/config.site export LC_ALL=POSIX export LFS_MAKEFLAGS=-j$(nproc) EOF # 重新加载bashrc source ~/.bashrc # 验证环境变量 echo &#34;LFS=$LFS&#34; echo &#34;LFS_TGT=$LFS_TGT&#34; echo &#34;PATH=$PATH&#34; echo &#34;MAKEFLAGS=$LFS_MAKEFLAGS&#34; 创建构建脚本 # 创建构建日志目录 mkdir -pv $LFS/logs # 创建构建脚本模板 cat &gt; $LFS/build.sh &lt;&lt; &#34;EOF&#34; #!/bin/bash # LFS构建脚本模板 set -e # 遇到错误立即退出 # 日志函数 log() { echo &#34;$(date &#39;+%Y-%m-%d %H:%M:%S&#39;) - $*&#34; | tee -a $LFS/logs/build.log } # 错误处理 error_exit() { echo &#34;$(date &#39;+%Y-%m-%d %H:%M:%S&#39;) - ERROR: $*&#34; &gt;&amp;2 exit 1 } # 包构建函数 build_package() { local package_name=$1 local package_version=$2 local package_url=$3 log &#34;开始构建 $package_name-$package_version&#34; # 下载源码 if [ ! -f $LFS/sources/$package_name-$package_version.tar.xz ]; then wget -P $LFS/sources $package_url || error_exit &#34;下载 $package_name 失败&#34; fi # 解压源码 cd $LFS/sources tar -xf $package_name-$package_version.tar.xz cd $package_name-$package_version # 配置、编译、安装 # （具体命令根据包而定） log &#34;$package_name-$package_version 构建完成&#34; } # 主构建流程 main() { log &#34;开始LFS构建过程&#34; # 检查环境 if [ -z &#34;$LFS&#34; ]; then error_exit &#34;LFS环境变量未设置&#34; fi if [ ! -d &#34;$LFS&#34; ]; then error_exit &#34;LFS目录不存在: $LFS&#34; fi log &#34;环境检查通过，开始构建...&#34; } # 运行主函数 main &#34;$@&#34; EOF # 设置脚本执行权限 chmod +x $LFS/build.sh 🧪 系统验证 验证构建环境 # 检查所有环境变量 echo &#34;=== 环境变量检查 ===&#34; echo &#34;LFS: $LFS&#34; echo &#34;LFS_TGT: $LFS_TGT&#34; echo &#34;PATH: $PATH&#34; echo &#34;MAKEFLAGS: $MAKEFLAGS&#34; echo &#34;LC_ALL: $LC_ALL&#34; # 检查目录结构 echo -e &#34;
=== 目录结构检查 ===&#34; ls -la $LFS # 检查工具可用性 echo -e &#34;
=== 工具可用性检查 ===&#34; tools=&#34;bash sh gcc g++ make ld ar as nm strip ranlib&#34; for tool in $tools; do if command -v $tool &gt;/dev/null 2&gt;&amp;1; then echo &#34;✓ $tool: $(which $tool)&#34; else echo &#34;✗ $tool: 未找到&#34; fi done # 检查磁盘空间 echo -e &#34;
=== 磁盘空间检查 ===&#34; df -h $LFS # 检查内存 echo -e &#34;
=== 内存检查 ===&#34; free -h 备份配置 # 备份宿主系统配置 mkdir -pv $LFS/backup # 备份环境变量 env &gt; $LFS/backup/host_env.txt # 备份已安装包列表 case $(cat /etc/os-release | grep -E &#39;^ID=&#39; | cut -d&#39;=&#39; -f2 | tr -d &#39;&#34;&#39;) in arch) pacman -Q &gt; $LFS/backup/host_packages.txt ;; ubuntu|debian) dpkg --get-selections &gt; $LFS/backup/host_packages.txt ;; fedora|rhel|centos) rpm -qa &gt; $LFS/backup/host_packages.txt ;; *) echo &#34;未知发行版，无法备份包列表&#34; &gt; $LFS/backup/host_packages.txt ;; esac # 备份内核配置 cp /proc/config.gz $LFS/backup/ 2&gt;/dev/null || echo &#34;内核配置不可用&#34; 🚨 常见问题 权限问题 # 如果遇到权限问题，确保lfs用户有正确的权限 sudo chown -R lfs:lfs $LFS sudo chmod -R 755 $LFS 依赖缺失 # 检查并安装缺失的依赖 # Arch Linux sudo pacman -S --needed base-devel wget texinfo python bison # Ubuntu sudo apt install build-essential wget texinfo python3 bison 环境变量问题 # 确保环境变量正确设置 source ~/.bashrc echo $LFS echo $LFS_TGT 📚 相关资源 LFS官方文档 - 宿主系统要求 LFS官方文档 - 准备工作 Arch Wiki - LFS 最近更新: {{ .Lastmod.Format &ldquo;2006-01-02&rdquo; }}

TensorFlow基础教程 本教程将从零开始介绍TensorFlow的基础知识，包括环境搭建、基本概念、简单模型构建和训练。通过本教程，你将能够使用TensorFlow构建和训练基本的机器学习模型。
🛠️ 环境搭建 安装TensorFlow # CPU版本 pip install tensorflow # GPU版本（需要CUDA支持） pip install tensorflow[and-cuda] # 验证安装 python -c &#34;import tensorflow as tf; print(tf.config.list_physical_devices(&#39;GPU&#39; if tf.test.is_gpu_available() else &#39;CPU&#39;))&#34; 推荐开发环境 # 创建虚拟环境 conda create -n tf_env python=3.9 conda activate tf_env # 安装TensorFlow和相关依赖 pip install tensorflow numpy matplotlib jupyter pandas scikit-learn # 启动Jupyter Notebook jupyter notebook 🎯 基础概念 Hello TensorFlow import tensorflow as tf # 打印TensorFlow版本 print(f&#34;TensorFlow版本: {tf.__version__}&#34;) # 创建常量张量 hello = tf.constant(&#34;Hello, TensorFlow!&#34;) print(f&#34;常量: {hello.numpy()}&#34;) # 基本运算 a = tf.constant(5) b = tf.constant(3) print(f&#34;5 + 3 = {tf.add(a, b).numpy()}&#34;) print(f&#34;5 * 3 = {tf.multiply(a, b).numpy()}&#34;) 张量操作 import tensorflow as tf import numpy as np # 创建不同类型的张量 scalar = tf.constant(42) # 标量 vector = tf.constant([1, 2, 3, 4, 5]) # 向量 matrix = tf.constant([[1, 2], [3, 4], [5, 6]]) # 矩阵 tensor_3d = tf.constant(np.random.rand(2, 3, 4)) # 三维张量 print(f&#34;标量形状: {scalar.shape}&#34;) print(f&#34;向量形状: {vector.shape}&#34;) print(f&#34;矩阵形状: {matrix.shape}&#34;) print(f&#34;三维张量形状: {tensor_3d.shape}&#34;) # 张量运算 x = tf.constant([1, 2, 3, 4, 5]) y = tf.constant([6, 7, 8, 9, 10]) # 元素级运算 print(f&#34;x + y = {tf.add(x, y).numpy()}&#34;) print(f&#34;x * y = {tf.multiply(x, y).numpy()}&#34;) # 广播机制 matrix = tf.constant([[1, 2], [3, 4]]) vector = tf.constant([5, 6]) print(f&#34;矩阵 + 向量广播结果:
{tf.add(matrix, vector).numpy()}&#34;) 🏗️ 第一个神经网络 线性回归模型 import tensorflow as tf import numpy as np import matplotlib.pyplot as plt # 生成模拟数据 np.random.seed(42) X = np.random.rand(100, 1) * 10 y = 2 * X + 1 + np.random.randn(100, 1) * 0.5 # 构建模型 model = tf.keras.Sequential([ tf.keras.layers.Dense(1, input_shape=(1,)) ]) # 编译模型 model.compile( optimizer=&#39;sgd&#39;, # 随机梯度下降 loss=&#39;mse&#39;, # 均方误差 metrics=[&#39;mae&#39;] # 平均绝对误差 ) # 模型摘要 model.summary() # 训练模型 history = model.fit(X, y, epochs=100, verbose=0) # 预测 y_pred = model.predict(X) # 可视化结果 plt.figure(figsize=(12, 4)) plt.subplot(1, 2, 1) plt.scatter(X, y, alpha=0.5, label=&#39;真实数据&#39;) plt.plot(X, y_pred, color=&#39;red&#39;, label=&#39;预测结果&#39;) plt.xlabel(&#39;X&#39;) plt.ylabel(&#39;y&#39;) plt.title(&#39;线性回归结果&#39;) plt.legend() plt.subplot(1, 2, 2) plt.plot(history.history[&#39;loss&#39;]) plt.xlabel(&#39;Epoch&#39;) plt.ylabel(&#39;Loss&#39;) plt.title(&#39;训练损失曲线&#39;) plt.tight_layout() plt.show() print(f&#34;模型权重: {model.weights[0].numpy().flatten()}&#34;) print(f&#34;模型偏置: {model.weights[1].numpy()}&#34;) 分类模型 - MNIST手写数字识别 import tensorflow as tf from tensorflow.keras.datasets import mnist from tensorflow.keras.utils import to_categorical # 加载MNIST数据集 (x_train, y_train), (x_test, y_test) = mnist.load_data() # 数据预处理 x_train = x_train.reshape(-1, 784) / 255.0 # 展平并归一化 x_test = x_test.reshape(-1, 784) / 255.0 y_train = to_categorical(y_train, 10) # one-hot编码 y_test = to_categorical(y_test, 10) # 构建模型 model = tf.keras.Sequential([ tf.keras.layers.Dense(128, activation=&#39;relu&#39;, input_shape=(784,)), tf.keras.layers.Dropout(0.2), # Dropout防止过拟合 tf.keras.layers.Dense(64, activation=&#39;relu&#39;), tf.keras.layers.Dense(10, activation=&#39;softmax&#39;) # 输出层 ]) # 编译模型 model.compile( optimizer=&#39;adam&#39;, # Adam优化器 loss=&#39;categorical_crossentropy&#39;, # 交叉熵损失 metrics=[&#39;accuracy&#39;] # 准确率 ) # 训练模型 history = model.fit( x_train, y_train, batch_size=128, epochs=10, validation_split=0.1, # 验证集 verbose=1 ) # 评估模型 test_loss, test_acc = model.evaluate(x_test, y_test, verbose=0) print(f&#34;测试集准确率: {test_acc:.4f}&#34;) # 预测 predictions = model.predict(x_test[:5]) predicted_labels = tf.argmax(predictions, axis=1).numpy() true_labels = tf.argmax(y_test[:5], axis=1).numpy() print(&#34;预测结果:&#34;, predicted_labels) print(&#34;真实标签:&#34;, true_labels) 📊 数据处理 使用tf.data API import tensorflow as tf import numpy as np # 创建数据集 def create_dataset(): # 生成随机数据 X = np.random.rand(1000, 10) y = np.random.randint(0, 2, 1000) # 创建tf.data.Dataset dataset = tf.data.Dataset.from_tensor_slices((X, y)) # 数据预处理 def preprocess(x, y): # 归一化 x = (x - tf.reduce_mean(x)) / tf.math.reduce_std(x) return x, y # 应用预处理 dataset = dataset.map(preprocess) # 打乱和批处理 dataset = dataset.shuffle(buffer_size=100) dataset = dataset.batch(32) # 重复和预取 dataset = dataset.repeat() dataset = dataset.prefetch(tf.data.AUTOTUNE) return dataset # 使用数据集训练 dataset = create_dataset() model = tf.keras.Sequential([ tf.keras.layers.Dense(64, activation=&#39;relu&#39;, input_shape=(10,)), tf.keras.layers.Dense(32, activation=&#39;relu&#39;), tf.keras.layers.Dense(1, activation=&#39;sigmoid&#39;) ]) model.compile(optimizer=&#39;adam&#39;, loss=&#39;binary_crossentropy&#39;, metrics=[&#39;accuracy&#39;]) # 训练 model.fit(dataset, epochs=5, steps_per_epoch=10) 图像数据增强 from tensorflow.keras.preprocessing.image import ImageDataGenerator # 创建图像数据生成器 datagen = ImageDataGenerator( rotation_range=20, # 随机旋转角度 width_shift_range=0.1, # 水平平移 height_shift_range=0.1, # 垂直平移 shear_range=0.1, # 剪切变换 zoom_range=0.1, # 缩放 horizontal_flip=True, # 水平翻转 fill_mode=&#39;nearest&#39; # 填充模式 ) # 应用数据增强 # datagen.fit(x_train) # 如果需要的话 # enhanced_data = datagen.flow(x_train, y_train, batch_size=32) 🎨 自定义模型和层 自定义层 import tensorflow as tf class CustomDense(tf.keras.layers.Layer): def __init__(self, units, activation=None, **kwargs): super(CustomDense, self).__init__(**kwargs) self.units = units self.activation = tf.keras.activations.get(activation) def build(self, input_shape): # 创建权重 self.w = self.add_weight( name=&#39;kernel&#39;, shape=(input_shape[-1], self.units), initializer=&#39;glorot_uniform&#39;, trainable=True ) self.b = self.add_weight( name=&#39;bias&#39;, shape=(self.units,), initializer=&#39;zeros&#39;, trainable=True ) def call(self, inputs): # 前向传播 output = tf.matmul(inputs, self.w) + self.b if self.activation is not None: output = self.activation(output) return output def get_config(self): # 序列化配置 config = super(CustomDense, self).get_config() config.update({ &#39;units&#39;: self.units, &#39;activation&#39;: tf.keras.activations.serialize(self.activation) }) return config # 使用自定义层 model = tf.keras.Sequential([ CustomDense(128, activation=&#39;relu&#39;, input_shape=(784,)), CustomDense(64, activation=&#39;relu&#39;), CustomDense(10, activation=&#39;softmax&#39;) ]) 自定义模型 class CustomModel(tf.keras.Model): def __init__(self, num_classes): super(CustomModel, self).__init__() self.dense1 = tf.keras.layers.Dense(128, activation=&#39;relu&#39;) self.dense2 = tf.keras.layers.Dense(64, activation=&#39;relu&#39;) self.dense3 = tf.keras.layers.Dense(num_classes, activation=&#39;softmax&#39;) self.dropout = tf.keras.layers.Dropout(0.2) def call(self, inputs, training=False): x = self.dense1(inputs) x = self.dropout(x, training=training) x = self.dense2(x) x = self.dropout(x, training=training) return self.dense3(x) # 使用自定义模型 model = CustomModel(num_classes=10) model.compile(optimizer=&#39;adam&#39;, loss=&#39;sparse_categorical_crossentropy&#39;, metrics=[&#39;accuracy&#39;]) 🔧 模型保存和加载 保存和加载模型 import tensorflow as tf # 构建和训练模型 model = tf.keras.Sequential([ tf.keras.layers.Dense(64, activation=&#39;relu&#39;, input_shape=(10,)), tf.keras.layers.Dense(1, activation=&#39;sigmoid&#39;) ]) model.compile(optimizer=&#39;adam&#39;, loss=&#39;binary_crossentropy&#39;, metrics=[&#39;accuracy&#39;]) # 训练模型（这里使用随机数据作为示例） import numpy as np X_train = np.random.rand(100, 10) y_train = np.random.randint(0, 2, 100) model.fit(X_train, y_train, epochs=5, verbose=0) # 保存完整模型 model.save(&#39;my_model.h5&#39;) # HDF5格式 model.save(&#39;my_model&#39;) # TensorFlow SavedModel格式 # 加载模型 loaded_model_h5 = tf.keras.models.load_model(&#39;my_model.h5&#39;) loaded_model = tf.keras.models.load_model(&#39;my_model&#39;) # 比较预测结果 test_data = np.random.rand(5, 10) original_pred = model.predict(test_data) loaded_pred = loaded_model.predict(test_data) print(f&#34;预测结果一致: {np.allclose(original_pred, loaded_pred)}&#34;) 保存和加载权重 # 保存模型权重 model.save_weights(&#39;model_weights.h5&#39;) # 创建相同架构的新模型 new_model = tf.keras.Sequential([ tf.keras.layers.Dense(64, activation=&#39;relu&#39;, input_shape=(10,)), tf.keras.layers.Dense(1, activation=&#39;sigmoid&#39;) ]) # 加载权重 new_model.load_weights(&#39;model_weights.h5&#39;) # 验证权重是否相同 original_weights = model.get_weights() loaded_weights = new_model.get_weights() for i, (orig, loaded) in enumerate(zip(original_weights, loaded_weights)): print(f&#34;权重{i}一致: {np.allclose(orig, loaded)}&#34;) 📈 模型评估和可视化 评估指标 from sklearn.metrics import classification_report, confusion_matrix import seaborn as sns # 预测测试集 y_pred = model.predict(x_test) y_pred_classes = tf.argmax(y_pred, axis=1).numpy() y_true = tf.argmax(y_test, axis=1).numpy() # 分类报告 print(&#34;分类报告:&#34;) print(classification_report(y_true, y_pred_classes)) # 混淆矩阵 cm = confusion_matrix(y_true, y_pred_classes) plt.figure(figsize=(10, 8)) sns.heatmap(cm, annot=True, fmt=&#39;d&#39;, cmap=&#39;Blues&#39;) plt.xlabel(&#39;预测标签&#39;) plt.ylabel(&#39;真实标签&#39;) plt.title(&#39;混淆矩阵&#39;) plt.show() 训练历史可视化 import matplotlib.pyplot as plt # 训练历史 history = model.fit(x_train, y_train, validation_data=(x_val, y_val), epochs=20) # 绘制训练曲线 plt.figure(figsize=(12, 4)) # 损失曲线 plt.subplot(1, 2, 1) plt.plot(history.history[&#39;loss&#39;], label=&#39;训练损失&#39;) plt.plot(history.history[&#39;val_loss&#39;], label=&#39;验证损失&#39;) plt.xlabel(&#39;Epoch&#39;) plt.ylabel(&#39;Loss&#39;) plt.title(&#39;训练和验证损失&#39;) plt.legend() # 准确率曲线 plt.subplot(1, 2, 2) plt.plot(history.history[&#39;accuracy&#39;], label=&#39;训练准确率&#39;) plt.plot(history.history[&#39;val_accuracy&#39;], label=&#39;验证准确率&#39;) plt.xlabel(&#39;Epoch&#39;) plt.ylabel(&#39;Accuracy&#39;) plt.title(&#39;训练和验证准确率&#39;) plt.legend() plt.tight_layout() plt.show() 🚀 实际项目：房价预测 完整项目代码 import tensorflow as tf import numpy as np import pandas as pd from sklearn.model_selection import train_test_split from sklearn.preprocessing import StandardScaler # 生成模拟房价数据 np.random.seed(42) n_samples = 1000 # 特征：面积、房间数、年龄、距离市中心距离 areas = np.random.normal(100, 20, n_samples) # 平方米 rooms = np.random.randint(1, 6, n_samples) # 房间数 ages = np.random.randint(0, 50, n_samples) # 房屋年龄 distances = np.random.normal(10, 3, n_samples) # 距离市中心（公里） # 目标：房价（万元） prices = 50 + 0.8 * areas + 10 * rooms - 0.5 * ages - 2 * distances + np.random.normal(0, 10, n_samples) # 创建DataFrame data = pd.DataFrame({ &#39;area&#39;: areas, &#39;rooms&#39;: rooms, &#39;age&#39;: ages, &#39;distance&#39;: distances, &#39;price&#39;: prices }) # 数据预处理 features = [&#39;area&#39;, &#39;rooms&#39;, &#39;age&#39;, &#39;distance&#39;] X = data[features].values y = data[&#39;price&#39;].values # 标准化特征 scaler = StandardScaler() X_scaled = scaler.fit_transform(X) # 分割数据集 X_train, X_test, y_train, y_test = train_test_split(X_scaled, y, test_size=0.2, random_state=42) # 构建模型 model = tf.keras.Sequential([ tf.keras.layers.Dense(64, activation=&#39;relu&#39;, input_shape=(4,)), tf.keras.layers.Dense(32, activation=&#39;relu&#39;), tf.keras.layers.Dense(16, activation=&#39;relu&#39;), tf.keras.layers.Dense(1) # 回归问题，输出层无激活函数 ]) # 编译模型 model.compile( optimizer=&#39;adam&#39;, loss=&#39;mse&#39;, metrics=[&#39;mae&#39;, &#39;mse&#39;] ) # 训练模型 history = model.fit( X_train, y_train, batch_size=32, epochs=100, validation_split=0.2, callbacks=[ tf.keras.callbacks.EarlyStopping(patience=10, restore_best_weights=True), tf.keras.callbacks.ReduceLROnPlateau(factor=0.5, patience=5) ], verbose=1 ) 